import{_ as t,o as a,c as s,a0 as i}from"./chunks/framework.ysVzM4be.js";const w=JSON.parse('{"title":"The Main view is one surface with two sections","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0013-the-main-view-is-one-surface-with-two-sections.md","filePath":"adr/0013-the-main-view-is-one-surface-with-two-sections.md"}'),n={name:"adr/0013-the-main-view-is-one-surface-with-two-sections.md"};function o(r,e,c,d,l,h){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="the-main-view-is-one-surface-with-two-sections" tabindex="-1">The Main view is one surface with two sections <a class="header-anchor" href="#the-main-view-is-one-surface-with-two-sections" aria-label="Permalink to &quot;The Main view is one surface with two sections&quot;">​</a></h1><p>The control plane ran two fullscreen main views, a Tickets view and a Consultation view, switched with <code>t</code> and <code>v</code>, each with its own bottom lines, and the Consultation side never reached the control catalogue (issue #9). We decided to merge them into one Main view holding two accordion sections: the expanded section keeps its list pane and detail pane, the collapsed one shrinks to a header row, and <code>t</code>, <code>v</code>, or a header click expand a section. The Consultation section&#39;s header carries its attention facts, its controls join the catalogue under the new <code>consultation-list</code> and <code>consultation-detail</code> base modes, and its messages become Message facts. A Consultation that needs the operator must not hide behind a view switch, and the glossary&#39;s one Message line and one Action bar finally exist as one each.</p><h2 id="considered-options" tabindex="-1">Considered options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered options&quot;">​</a></h2><ul><li>Keep the two fullscreen views with a view switch. Consultation attention stays hidden behind a keypress, and the second message and action system keeps running.</li><li>One list pane with collapsible Tickets and Consultations groups sharing one detail pane. Collapsing hides only the rows, but each side loses its own master-detail layout.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Both sections keep their list selection and detail scroll while collapsed; a re-expand shows the same place.</li><li>The free-standing attention line and the Consultation status line disappear: attention facts live on the Consultation section&#39;s header row, and Consultation progress, notices, warnings, and errors ride the Message line.</li><li>No key letter changes: Consultation keys keep their letters and gain catalogue availability, the Action bar, and the Key guide.</li><li>The Main frame owns two header rows, so its minimum useful size rises with them: 40 columns by 9 rows is the shortest terminal that holds both headers, one real pane row, the Message line, and the Action bar. Below it the compact frame drops the headers with the panes.</li><li>The Agent terminal and the response editor join the interaction mode set, so the Action bar and the Key guide state the keys those surfaces actually accept: the configured exit key, and Send and Keep draft.</li></ul>',6)])])}const p=t(n,[["render",o]]);export{w as __pageData,p as default};
